def solve(data):
    cutoff = data.get('cutoff', 10**9)
    selected = {}

    for position, event in enumerate(data.get('events', [])):
        if event.get('sequence', 0) > cutoff:
            continue

        event_id = event.get('id', f'anonymous:{position}')
        revision = event.get('revision', 0)
        previous = selected.get(event_id)
        if previous is None or revision >= previous[0]:
            selected[event_id] = (revision, position, event)

    balances = dict(data.get('opening', {}))
    rounding = data.get('rounding', 'half_up')
    for _, _, event in selected.values():
        if event.get('void') is True:
            continue
        key = f"{event.get('account', 'default')}|{event.get('currency', 'USD')}"
        balances[key] = balances.get(key, 0) + amount(event, rounding)

    return {'balances': balances}
